parameters.jsCode:
const items = $input.all();
const url = items.map(
  (item) => JSON.parse(item.json.body.data.resultJson).resultUrls[0],
);
return { url: url[0] };

parameters.jsonBody:
={
  "query": "mutation CreateFacebookPost($text: String!, $channelId: ChannelId!, $imageUrl: String!) { createPost(input: { text: $text, channelId: $channelId, schedulingType: automatic, mode: shareNow, metadata: { facebook: { type: post } }, assets: [{ image: { url: $imageUrl } }] }) { ... on PostActionSuccess { post { id text status } } ... on MutationError { message } } }",
  "variables": {
    "text": {{ JSON.stringify($('facebook caption generation agent').item.json.output) }},
    "channelId": "REPLACE_WITH_BUFFER_FACEBOOK_CHANNEL_ID",
    "imageUrl": "{{ $('Code in JavaScript').item.json.url }}"
  }
}

